package com.example.domain.model.i18n

internal object DuaEs1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Al despertar", "Alabado sea Allah, que nos devolvió la vida después de habernos dado muerte (el sueño), y hacia Él es el retorno.", "Se recita al despertar, en agradecimiento a Allah.", "El Profeta ﷺ la recitaba al despertar — comenzar el día con gratitud y el recuerdo del más allá."),
        "dua_leaving_home" to DuaText("Al salir de casa", "En el nombre de Allah, en Allah confío, no hay poder ni fuerza sino en Allah.", "Se recita al salir de casa, para pedir protección.", "Se le dice entonces: has sido guiado, protegido y amparado, y el diablo se aparta de él."),
        "dua_anxiety_distress" to DuaText("Súplica contra la angustia y la tristeza", "Oh Allah, me refugio en Ti de la angustia y la tristeza, de la incapacidad y la pereza, de la avaricia y la cobardía, del peso de las deudas y del dominio de los hombres.", "En momentos de angustia, tristeza, deudas o agobio.", "El Profeta ﷺ recitaba esta súplica con frecuencia contra la angustia, la pereza y las deudas."),
        "dua_sayyidul_istighfar" to DuaText("El maestro del perdón", "Oh Allah, Tú eres mi Señor, no hay más divinidad que Tú. Me creaste y soy Tu siervo, y me mantengo en Tu pacto y promesa en la medida de lo posible. Me refugio en Ti del mal que he cometido. Reconozco Tus favores sobre mí y reconozco mi pecado, así que perdóname, pues nadie perdona los pecados sino Tú.", "Mañana y tarde — la mejor súplica de arrepentimiento enseñada por el Profeta ﷺ.", "Quien la dice al atardecer con convicción y muere esa noche entra al Paraíso; lo mismo si la dice al amanecer."),
        "dua_parents" to DuaText("Súplica por los padres", "Señor mío, ten misericordia de ellos como ellos me criaron de pequeño.", "Súplica coránica por los padres, en agradecimiento por su crianza.", "Allah mismo ordenó esta súplica por los padres en el Corán."),
        "dua_entering_mosque" to DuaText("Al entrar en la mezquita", "Oh Allah, ábreme las puertas de Tu misericordia.", "Se recita al entrar en la mezquita con el pie derecho.", "El Profeta ﷺ enseñó esta súplica al entrar en la mezquita."),
        "dua_morning_asbahna" to DuaText("Recuerdo de la mañana", "Amanecimos y con nosotros amaneció el reino de Allah. Alabado sea Allah. No hay más divinidad que Allah, Único, sin asociado. Suyo es el reino, Suya es la alabanza, y Él tiene poder sobre todas las cosas.", "Súplica profética para la mañana.", "Comenzar el día reconociendo el reino y la unicidad de Allah."),
        "dua_evening_amsayna" to DuaText("Recuerdo de la tarde", "Anochecimos y con nosotros anocheció el reino de Allah. Alabado sea Allah. No hay más divinidad que Allah, Único, sin asociado. Suyo es el reino, Suya es la alabanza, y Él tiene poder sobre todas las cosas.", "Súplica profética para la tarde.", "Comenzar la noche reconociendo el reino y la unicidad de Allah."),
        "dua_bismillah_la_yadurru" to DuaText("Protección contra todo mal", "En el nombre de Allah, con cuyo nombre nada en la tierra ni en el cielo puede causar daño, y Él es el que todo lo oye, el que todo lo sabe.", "Se recita tres veces por la mañana y tres por la tarde.", "Quien la dice tres veces mañana y tarde, nada podrá dañarle."),
        "dua_raditu_billahi" to DuaText("Satisfecho con Allah como Señor", "Estoy satisfecho con Allah como Señor, con el Islam como religión, y con Muhammad ﷺ como profeta.", "Se recita tres veces mañana y tarde.", "Allah se compromete a complacerlo el Día del Juicio."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah me basta)", "Allah me basta, no hay más divinidad que Él, en Él confío, y Él es el Señor del Trono inmenso.", "Se recita siete veces mañana y tarde.", "Versículo coránico; Allah basta ante las preocupaciones de esta vida y la otra."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Gloria y alabanza a Allah", "Gloria a Allah y alabado sea.", "Se recita cien veces al día.", "Quien lo dice cien veces al día, se le perdonan sus pecados aunque sean como la espuma del mar."),
        "dua_tahleel_100" to DuaText("No hay más divinidad que Allah, Único", "No hay más divinidad que Allah, Único, sin asociado. Suyo es el reino, Suya es la alabanza, y Él tiene poder sobre todas las cosas.", "Gran mérito al recitarlo cien veces al día.", "Equivale a liberar diez esclavos, se le anotan cien buenas obras, se le borran cien pecados, y queda protegido del diablo hasta el anochecer."),
        "dua_leaving_mosque" to DuaText("Al salir de la mezquita", "Oh Allah, Te pido de Tu favor.", "Se recita al salir de la mezquita con el pie izquierdo.", "Pedir el favor y el sustento de Allah al salir de la mezquita."),
        "dua_after_adhan" to DuaText("Después del llamado a la oración", "Oh Allah, Señor de esta llamada perfecta y de la oración que se va a establecer, concede a Muhammad el rango intercesor y la virtud, y elévalo a la posición loable que le has prometido.", "Justo después de terminar el adhan.", "Quien la recita obtiene la intercesión del Profeta ﷺ el Día del Juicio."),
        "dua_after_salah_istighfar" to DuaText("Después de la oración obligatoria", "Pido perdón a Allah (tres veces). Oh Allah, Tú eres la Paz, y de Ti proviene la paz, bendito seas, oh Poseedor de la Majestad y la Generosidad.", "Justo después del saludo final de la oración.", "El Profeta ﷺ la recitaba después de cada oración obligatoria."),
        "dua_after_salah_help_dhikr" to DuaText("Ayúdame a recordarte", "Oh Allah, ayúdame a recordarte, a agradecerte y a adorarte de la mejor manera.", "Después de cada oración — recomendación del Profeta ﷺ a Mu'adh.", "Recomendación profética especial para la excelencia y constancia en la adoración."),
        "dua_ayatul_kursi" to DuaText("El Versículo del Trono tras la oración", "Allah, no hay más divinidad que Él, el Viviente, el Sustentador de toda la existencia. Ni la somnolencia ni el sueño Lo afectan. Suyo es cuanto hay en los cielos y en la tierra. ¿Quién puede interceder ante Él sino con Su permiso? Conoce lo que hay ante ellos y lo que hay detrás de ellos, y ellos no abarcan nada de Su conocimiento excepto lo que Él quiere. Su Trono abarca los cielos y la tierra, y no Le resulta pesado custodiarlos, y Él es el Altísimo, el Grandioso.", "Después de cada oración obligatoria y antes de dormir.", "Quien lo recita tras cada oración obligatoria, solo la muerte le impide entrar al Paraíso; antes de dormir, queda protegido hasta la mañana."),
        "dua_before_sleep" to DuaText("Antes de dormir", "En Tu nombre, oh Allah, muero (duermo) y vivo (despierto).", "Se recita después de recostarse.", "El Profeta ﷺ la recitaba antes de dormir."),
        "dua_sleep_tasbeeh" to DuaText("El tasbih de Fátima antes de dormir", "Gloria a Allah (33 veces), alabado sea Allah (33 veces), Allah es el más grande (34 veces).", "Antes de dormir — enseñado por el Profeta ﷺ a Fátima y Ali.", "El Profeta ﷺ dijo que esto era mejor para ellos que un sirviente."),
        "dua_sleep_qina_adhab" to DuaText("Protección del castigo", "Oh Allah, protégeme de Tu castigo el día en que resucites a Tus siervos.", "Con la mano derecha bajo la mejilla, se recita tres veces.", "Recuerda la muerte y prepara para el más allá antes de dormir."),
        "dua_bad_dream" to DuaText("Al tener una pesadilla", "Me refugio en Allah del demonio maldito.", "Ante una pesadilla: soplar levemente tres veces hacia la izquierda y cambiar de posición.", "La pesadilla no le hará daño; no debe contársela a nadie."),
        "dua_yunus" to DuaText("La súplica del profeta Jonás (Yunus)", "No hay más divinidad que Tú, ¡glorificado seas! En verdad fui de los injustos.", "La súplica del profeta Jonás en el vientre de la ballena — para toda aflicción.", "Ningún musulmán la ha suplicado por un asunto sin que Allah le respondiera."),
        "dua_karb" to DuaText("Súplica ante una gran aflicción", "No hay más divinidad que Allah, el Grandioso, el Indulgente. No hay más divinidad que Allah, Señor del Trono inmenso. No hay más divinidad que Allah, Señor de los cielos, de la tierra y del noble Trono.", "Ante una gran aflicción y angustia.", "El Profeta ﷺ la recitaba en momentos de aflicción."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Oh Viviente, oh Sustentador", "Oh Viviente, oh Sustentador, por Tu misericordia imploro auxilio.", "Cuando un asunto se vuelve muy pesado.", "El Profeta ﷺ la decía cuando algo le preocupaba."),
        "dua_hasbunallah" to DuaText("Allah nos basta", "Allah nos basta y Él es el mejor protector.", "Ante el temor a un enemigo o un gran peligro.", "La dijo Abraham cuando fue arrojado al fuego, y el Profeta ﷺ ante el peligro."),
        "dua_entering_home" to DuaText("Al entrar en casa", "En el nombre de Allah entramos, en el nombre de Allah salimos, y en Allah, nuestro Señor, confiamos.", "Se recita al entrar en casa, mencionando el nombre de Allah y el saludo.", "Quien menciona a Allah al entrar en su casa y al comer, el diablo dice: no hay refugio ni cena para vosotros."),
        "dua_travel" to DuaText("Súplica del viaje", "Gloria a Quien nos ha sometido esto, pues nosotros no hubiéramos podido dominarlo; y en verdad, hacia nuestro Señor hemos de volver.", "Se recita al montar, después de decir Allahu Akbar tres veces.", "Súplica profética del viaje para protección y bendición."),
        "dua_entering_market" to DuaText("Al entrar al mercado", "No hay más divinidad que Allah, Único, sin asociado. Suyo es el reino y la alabanza. Él da la vida y la muerte, y Él vive y no muere jamás. En Su mano está el bien, y Él tiene poder sobre todas las cosas.", "Se recita al entrar al mercado.", "Se relata en el hadiz un gran mérito por esta súplica."),
        "dua_adam_forgiveness" to DuaText("La súplica de Adán", "Señor nuestro, nos hemos perjudicado a nosotros mismos; si no nos perdonas y nos tienes misericordia, seremos de los perdedores.", "La súplica de arrepentimiento de Adán y Eva.", "El primer arrepentimiento de la humanidad — aceptado por Allah."),
        "dua_abu_bakr" to DuaText("Súplica enseñada a Abu Bakr", "Oh Allah, me he perjudicado mucho a mí mismo, y nadie perdona los pecados sino Tú; concédeme un perdón de Tu parte y ten misericordia de mí, pues Tú eres el Perdonador, el Misericordioso.", "Enseñada por el Profeta ﷺ a Abu Bakr para recitar en la oración.", "Súplica profética para el final de la oración."),
        "dua_astaghfirullah_atubu" to DuaText("El arrepentimiento diario", "Pido perdón a Allah y me arrepiento ante Él.", "El Profeta ﷺ pedía perdón más de setenta veces al día.", "El Profeta ﷺ dijo que pedía perdón a Allah más de setenta veces al día."),
        "dua_laylatul_qadr" to DuaText("Súplica de la Noche del Decreto", "Oh Allah, Tú eres Indulgente, amas el perdón, así que perdóname.", "Enseñada a Aisha para la Noche del Decreto.", "Súplica especial de las últimas diez noches del Ramadán y de Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("El frescor de los ojos (esposa e hijos)", "Señor nuestro, concédenos en nuestras esposas y descendencia el frescor de los ojos, y haznos guías de los piadosos.", "Súplica coránica por un cónyuge y unos hijos virtuosos.", "Para la serenidad del hogar y una descendencia virtuosa."),
        "dua_righteous_children" to DuaText("Por una descendencia virtuosa", "Señor mío, concédeme de Tu parte una descendencia pura; en verdad Tú eres Quien escucha la súplica.", "La súplica de Zacarías.", "Súplica coránica para pedir descendencia."),
        "dua_ibrahim_prayer_family" to DuaText("Los que establecen la oración", "Señor mío, hazme de los que establecen la oración, y también a mi descendencia. Señor nuestro, acepta mi súplica. Señor nuestro, perdóname a mí, a mis padres y a los creyentes el día en que se establezca la cuenta.", "La súplica de Abraham por sí mismo y su descendencia.", "Se recita generalmente al final de la oración."),
        "dua_newlywed" to DuaText("Felicitación a los recién casados", "Que Allah te bendiga, derrame Su bendición sobre ti, y os una en el bien.", "Se dice a quien se casa.", "Felicitación profética para el matrimonio."),
        "dua_before_eating" to DuaText("Antes de comer", "En el nombre de Allah. (Si se olvida:) En el nombre de Allah, al principio y al final.", "Antes de comer; si se olvida, se dice durante la comida.", "Al decir el Bismillah, el diablo no participa de la comida."),
        "dua_after_eating" to DuaText("Después de comer", "Alabado sea Allah, que me alimentó con esto y me lo concedió sin fuerza ni poder de mi parte.", "Después de terminar de comer.", "A quien la dice se le perdonan sus pecados pasados."),
        "dua_host" to DuaText("Por el anfitrión", "Oh Allah, bendice lo que les has dado como sustento, perdónalos y ten misericordia de ellos.", "Después de comer en casa de alguien, por el anfitrión.", "Agradecimiento profético al anfitrión."),
        "dua_breaking_fast" to DuaText("Al romper el ayuno", "Se fue la sed, se humedecieron las venas, y la recompensa quedó confirmada, si Allah quiere.", "Al momento del iftar.", "El Profeta ﷺ lo decía al romper el ayuno."),
        "dua_new_clothes" to DuaText("Al vestir ropa nueva", "Oh Allah, Tuya es la alabanza, Tú me has vestido con esto; Te pido su bien y el bien para lo que fue hecho, y me refugio en Ti de su mal y del mal para lo que fue hecho.", "Al ponerse ropa nueva, nombrándola.", "El Profeta ﷺ lo decía al vestir ropa nueva."),
        "dua_rabbana_atina" to DuaText("El bien en esta vida y en la otra", "Señor nuestro, concédenos el bien en esta vida y el bien en la otra, y protégenos del castigo del Fuego.", "La súplica que el Profeta ﷺ hacía con más frecuencia.", "Súplica que reúne todo el bien de esta vida y la otra."),
        "dua_rabbi_zidni_ilma" to DuaText("Aumento del conocimiento", "Señor mío, auméntame en conocimiento.", "Para pedir el aumento del saber.", "Allah ordenó al Profeta ﷺ pedir aumento solo en el conocimiento."),
        "dua_musa_sharh_sadr" to DuaText("La apertura del pecho (Moisés)", "Señor mío, abre mi pecho, facilita mi tarea, y desata un nudo de mi lengua para que comprendan mis palabras.", "Antes de un examen, un discurso, o una tarea difícil.", "La súplica de Moisés — sosiego del corazón y facilidad en la tarea."),
        "dua_la_tuzigh" to DuaText("La firmeza del corazón", "Señor nuestro, no desvíes nuestros corazones después de habernos guiado, y concédenos, de Tu parte, misericordia; en verdad Tú eres el Gran Dador.", "Para la firmeza del corazón en la guía.", "Súplica para la perseverancia en la fe."),
        "dua_ya_muqallib" to DuaText("Oh Tú que vuelves los corazones", "Oh Tú que vuelves los corazones, afirma mi corazón en Tu religión.", "El Profeta ﷺ la repetía con frecuencia.", "La súplica más frecuente del Profeta ﷺ según Umm Salama."),
        "dua_la_tuakhidhna" to DuaText("Los últimos versículos de la sura Al-Baqara", "Señor nuestro, no nos castigues si olvidamos o cometemos un error. Señor nuestro, no nos impongas una carga como la impusiste a quienes nos precedieron. Señor nuestro, no nos cargues con lo que no podemos soportar, perdónanos, absuélvenos y ten misericordia de nosotros. Tú eres nuestro Protector, auxílianos contra el pueblo incrédulo.", "Antes de dormir — los dos últimos versículos de la sura Al-Baqara.", "A quien los recita en una noche, le bastan."),
        "dua_visiting_sick" to DuaText("Visita al enfermo", "Pido a Allah el Grandioso, Señor del Trono inmenso, que te cure.", "Siete veces al visitar al enfermo.", "Si su plazo no ha llegado, Allah lo cura."),
        "dua_ruqyah_pain" to DuaText("Por un dolor del cuerpo", "Me refugio en Allah y Su poder del mal que siento y temo.", "Poner la mano sobre el dolor, decir tres veces Bismillah y luego siete veces esta súplica.", "Enseñada por el Profeta ﷺ a Uzmán ibn Abi al-As para el dolor."),
        "dua_ruqyah_nabawi" to DuaText("La ruqia profética para el enfermo", "Oh Allah, Señor de la gente, quita el mal, cura, Tú eres el Curador, no hay más cura que la Tuya, una cura que no deja enfermedad alguna.", "Pasando la mano sobre el enfermo.", "El Profeta ﷺ lo decía al visitar a su familia enferma."),
        "dua_kalimat_tammat" to DuaText("Refugio en las palabras perfectas de Allah", "Me refugio en las palabras perfectas de Allah del mal de lo que Él ha creado.", "Al llegar a un lugar o por la tarde.", "Quien se instala en un lugar y la dice, nada le dañará hasta que se marche."),
        "dua_evil_eye" to DuaText("Protección de los niños (mal de ojo)", "Os encomiendo a ambos a la protección de las palabras perfectas de Allah, de todo demonio, de toda criatura venenosa, y de todo ojo dañino.", "El Profeta ﷺ la recitaba sobre Hasan y Husáin.", "Súplica profética para proteger a los niños del mal de ojo y del mal."),
        "dua_seeing_afflicted" to DuaText("Al ver a alguien afligido", "Alabado sea Allah, que me libró de lo que te afligió a ti, y me favoreció claramente sobre muchas de Sus criaturas.", "Al ver a alguien afligido (se dice para sí mismo).", "Quien la dice quedará protegido de esa aflicción."),
        "dua_istikhara" to DuaText("La oración de consulta (Istikhara)", "Oh Allah, te consulto por medio de Tu conocimiento, y te pido capacidad por medio de Tu poder, y te pido de Tu inmenso favor, pues Tú tienes poder y yo no, Tú sabes y yo no sé, y Tú eres el Gran Conocedor de lo oculto. Oh Allah, si sabes que este asunto es bueno para mí en mi religión, mi vida y el desenlace de mi destino, entonces decrétalo para mí, facilítamelo, y luego bendícemelo. Y si sabes que es malo para mí en mi religión, mi vida y el desenlace de mi destino, entonces apártalo de mí y apártame de él, y decreta para mí el bien donde sea que esté, y hazme estar conforme con ello.", "Después de dos unidades de oración voluntaria, para pedir el bien en un asunto lícito.", "El Profeta ﷺ enseñaba la Istikhara a sus compañeros como una sura del Corán."),
        "dua_allahumma_bika_asbahna" to DuaText("Oh Allah, por Ti amanecimos", "Oh Allah, por Ti amanecimos y por Ti anochecimos, por Ti vivimos y por Ti morimos, y hacia Ti es el retorno.", "Por la mañana.", "El Profeta ﷺ la enseñaba mañana y tarde."),
        "dua_allahumma_bika_amsayna" to DuaText("Oh Allah, por Ti anochecimos", "Oh Allah, por Ti anochecimos y por Ti amanecimos, por Ti vivimos y por Ti morimos, y hacia Ti es el destino.", "Por la tarde.", "El Profeta ﷺ la enseñaba mañana y tarde."),
        "dua_afiyah_morning" to DuaText("Súplica por la salud", "Oh Allah, Te pido el perdón y la salud en esta vida y en la otra.", "El Profeta ﷺ nunca la dejaba, mañana y tarde.", "A nadie se le ha dado nada mejor que la buena salud."),
        "dua_afini_fi_badani" to DuaText("Salud del cuerpo, del oído y de la vista", "Oh Allah, dame salud en mi cuerpo, dame salud en mi oído, dame salud en mi vista; no hay más divinidad que Tú.", "Tres veces mañana y tarde.", "Súplica para preservar la salud y los sentidos."),
        "dua_ya_hayyu_aslih" to DuaText("Arregla todos mis asuntos", "Oh Viviente, oh Sustentador, por Tu misericordia imploro auxilio; arregla todos mis asuntos y no me dejes a mi suerte ni el parpadeo de un ojo.", "El Profeta ﷺ recomendó a Fátima decirla mañana y tarde.", "Pedir la ayuda de Allah en todo asunto."),
        "dua_subhanallah_adada_khalqihi" to DuaText("El tasbih de Yuwairiya", "Gloria a Allah y alabado sea, tanto como el número de Sus criaturas, tanto como Su complacencia, tanto como el peso de Su Trono, y tanto como la tinta de Sus palabras.", "Tres veces por la mañana — equivale a horas de recuerdo.", "Estas cuatro palabras, dichas tres veces, pesan más que el recuerdo desde la mañana hasta el mediodía."),
        "dua_salawat" to DuaText("La oración abrahámica por el Profeta", "Oh Allah, bendice a Muhammad y a la familia de Muhammad como bendijiste a Abraham y a la familia de Abraham; en verdad Tú eres Digno de alabanza y de gloria. Oh Allah, bendice a Muhammad y a la familia de Muhammad como bendijiste a Abraham y a la familia de Abraham; en verdad Tú eres Digno de alabanza y de gloria.", "En la oración y en todo momento.", "Quien pide una bendición para el Profeta ﷺ, Allah le concede diez bendiciones."),
        "dua_wudu_after" to DuaText("Después de la ablución", "Atestiguo que no hay más divinidad que Allah, Único, sin asociado, y atestiguo que Muhammad es Su siervo y mensajero. Oh Allah, hazme de los que se arrepienten y de los que se purifican.", "Después de completar la ablución.", "Se le abren las ocho puertas del Paraíso, y entra por la que desee."),
        "dua_wudu_before" to DuaText("Antes de la ablución", "En el nombre de Allah.", "Al comenzar la ablución.", "Quien no menciona el nombre de Allah no tiene una ablución (completa)."),
        "dua_istiftah" to DuaText("La súplica de apertura de la oración", "Gloria a Ti, oh Allah, y alabado seas; bendito sea Tu nombre, exaltada sea Tu grandeza, no hay más divinidad que Tú.", "Al comenzar la oración, justo después del takbir inicial.", "La súplica profética de apertura de la oración."),
        "dua_ruku" to DuaText("En la inclinación (ruku')", "Gloria a mi Señor, el Grandioso.", "Al menos tres veces durante el ruku'.", "El tasbih profético del ruku'."),
        "dua_sujood" to DuaText("En la postración (sujud)", "Gloria a mi Señor, el Altísimo.", "Al menos tres veces durante el sujud.", "El siervo está más cerca de su Señor cuando está postrado."),
        "dua_rising_ruku" to DuaText("Al levantarse del ruku'", "Allah escucha a quien Lo alaba. Señor nuestro, a Ti sea la alabanza.", "Al levantarse del ruku' y quedar de pie.", "A quien sus palabras coincidan con las de los ángeles, se le perdonan sus pecados pasados."),
        "dua_between_sajdas" to DuaText("Entre las dos postraciones", "Señor mío, perdóname; Señor mío, perdóname.", "Sentado entre las dos postraciones.", "La súplica profética de esta posición sentada."),
        "dua_before_salam_four" to DuaText("Refugio de cuatro cosas antes del saludo final", "Oh Allah, me refugio en Ti del castigo del Infierno, del castigo de la tumba, de las pruebas de la vida y de la muerte, y del mal de la prueba del Falso Mesías (Dayyal).", "Después del último tashahhud y la oración por el Profeta, antes del saludo final.", "El Profeta ﷺ ordenó refugiarse de estas cuatro cosas."),
        "dua_qunoot_witr" to DuaText("La súplica del Qunut en el Witr", "Oh Allah, guíame entre quienes has guiado, dame salud entre quienes has dado salud, cuídame entre quienes has cuidado, bendice lo que me has dado, y protégeme del mal que has decretado. Tú decretas y nada puede decretarse contra Ti; a quien Tú proteges nunca es humillado. Bendito seas, Señor nuestro, y exaltado.", "En la oración del Witr — enseñada por el Profeta ﷺ a Al-Hasan ibn Ali.", "La súplica profética del Qunut en el Witr."),
        "dua_qunoot_hanafi" to DuaText("El Qunut (Allahumma inna nasta'inuk)", "Oh Allah, te pedimos ayuda, perdón y guía, creemos en Ti y confiamos en Ti, te alabamos de la mejor manera, te agradecemos y no te negamos, y abandonamos a quien te desobedece. Oh Allah, solo a Ti adoramos, para Ti oramos y nos postramos, hacia Ti nos apresuramos, esperamos Tu misericordia y tememos Tu castigo; en verdad Tu castigo alcanzará a los incrédulos.", "En el Witr — práctica de la escuela hanafí.", "Relatado de Umar en el Qunut."),
        "dua_sleep_aslamtu" to DuaText("Las últimas palabras antes de dormir", "Oh Allah, me entrego a Ti por completo, confío mi asunto a Ti, apoyo mi espalda en Ti, por deseo y por temor hacia Ti. No hay refugio ni salvación de Ti sino en Ti. Creo en Tu Libro que has revelado y en Tu Profeta que has enviado.", "Después de la ablución, acostado sobre el lado derecho — las últimas palabras.", "Si muere esa noche, muere en la naturaleza pura (fitra)."),
        "dua_waking_night" to DuaText("Al despertar por la noche", "No hay más divinidad que Allah, Único, sin asociado. Suyo es el reino, Suya es la alabanza, y Él tiene poder sobre todas las cosas. Alabado sea Allah, gloria a Allah, no hay más divinidad que Allah, Allah es el más grande, no hay poder ni fuerza sino en Allah. Oh Allah, perdóname.", "Al despertar por la noche.", "Su súplica es escuchada, y si hace la ablución y ora, su oración es aceptada."),
        "dua_hamm_ibn_masud" to DuaText("Súplica contra la angustia (Ibn Masud)", "Oh Allah, soy Tu siervo, hijo de Tu siervo, hijo de Tu sierva, mi frente está en Tus manos, Tu juicio se cumple en mí, Tu decreto sobre mí es justo. Te pido por todo nombre que Te pertenece, con el que Te has nombrado, o que has revelado en Tu Libro, o que has enseñado a alguna de Tus criaturas, o que has reservado para Ti en el conocimiento de lo oculto, que hagas del Corán la primavera de mi corazón, la luz de mi pecho, el fin de mi tristeza y la disipación de mi angustia.", "En momentos de angustia y tristeza — Allah los transforma en alegría.", "Allah disipa su angustia y tristeza y las reemplaza con alegría."),
        "dua_difficulty_sahl" to DuaText("Cuando un asunto es difícil", "Oh Allah, nada es fácil salvo lo que Tú haces fácil, y Tú haces fácil, si quieres, lo que es difícil.", "Cuando un asunto parece difícil.", "Para facilitar exámenes y asuntos difíciles."),
        "dua_musibah" to DuaText("Ante una desgracia (Istiryá')", "Pertenecemos a Allah y a Él hemos de volver. Oh Allah, recompénsame en mi desgracia y concédeme algo mejor a cambio de ella.", "Ante cualquier pérdida o desgracia.", "Allah ciertamente concede un mejor reemplazo — como sucedió con Umm Salama."),
        "dua_debt" to DuaText("Para liberarse de una deuda", "Oh Allah, bástame con lo lícito frente a lo ilícito, y hazme independiente, por Tu favor, de todo lo que no seas Tú.", "Para el pago de una deuda — enseñada por el Profeta ﷺ a Ali.", "Aunque la deuda fuera como una montaña, Allah la hará pagar."),
        "dua_anger" to DuaText("Ante la ira", "Me refugio en Allah del demonio maldito.", "Ante la ira.", "El Profeta ﷺ dijo que su ira se calmaría al decirlo."),
        "dua_waswasa" to DuaText("Contra las dudas insinuadas en la fe", "Creo en Allah y en Sus mensajeros.", "Ante dudas que el diablo insinúa sobre la fe.", "Se dice esto y se deja de pensar en la duda."),
        "dua_travel_full" to DuaText("La súplica completa del viaje", "Oh Allah, Te pedimos, en este viaje, virtud y piedad, y obras que Te complazcan. Oh Allah, facilítanos este viaje y acorta su distancia. Oh Allah, Tú eres el Compañero en el viaje y el Guardián de la familia que queda atrás.", "Al comenzar el viaje, después de «Gloria a Quien nos ha sometido esto...».", "La súplica profética completa del viaje."),
        "dua_return_travel" to DuaText("Al regresar de un viaje", "Regresamos, arrepentidos, adoradores, alabando a nuestro Señor.", "Al regresar de un viaje.", "El Profeta ﷺ la decía al volver de un viaje."),
        "dua_farewell_traveller" to DuaText("Despedida de un viajero", "Encomiendo a Allah tu religión, tu responsabilidad y el resultado final de tus obras.", "Al despedir a un viajero.", "Lo que se encomienda a Allah nunca se pierde."),
        "dua_entering_town" to DuaText("Al llegar a un lugar nuevo", "Me refugio en las palabras perfectas de Allah del mal de lo que Él ha creado.", "Al instalarse en un lugar o una nueva ciudad.", "Nada le dañará hasta que se marche de ese lugar."),
        "dua_boarding_ship" to DuaText("Al embarcar en un barco", "En el nombre de Allah, que navegue y que ancle. En verdad, mi Señor es Perdonador, Misericordioso.", "Al embarcar — palabras del profeta Noé.", "Versículo coránico — la súplica del arca de Noé."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Arrepentimiento por el Viviente, el Sustentador", "Pido perdón a Allah, no hay más divinidad que Él, el Viviente, el Sustentador, y me arrepiento ante Él.", "Para arrepentirse.", "Sus pecados son perdonados aunque haya huido del campo de batalla."),
        "dua_rabbighfir_warham" to DuaText("Señor, perdona y ten misericordia", "Señor mío, perdona y ten misericordia, Tú eres el mejor de los misericordiosos.", "Súplica coránica — perdón y misericordia.", "Último versículo de la sura Al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Expiación de la reunión", "Gloria a Ti, oh Allah, y alabado seas; atestiguo que no hay más divinidad que Tú, Te pido perdón y me arrepiento ante Ti.", "Al levantarse de una reunión.", "Expiación de lo inútil que se haya dicho en la reunión."),
        "dua_jami_forgiveness" to DuaText("La súplica general de perdón", "Oh Allah, perdona mi error, mi ignorancia, mi exceso en mis asuntos, y lo que Tú conoces mejor que yo.", "Súplica general que el Profeta ﷺ solía recitar.", "Súplica abarcadora que el Profeta ﷺ repetía con frecuencia."),
        "dua_parents_nuh" to DuaText("La súplica de Noé por los padres", "Señor mío, perdóname a mí, a mis padres, y a quien entre en mi casa siendo creyente, y a todos los creyentes y creyentes.", "Por los padres y los creyentes.", "La súplica del profeta Noé."),
        "dua_shukr_parents" to DuaText("Gratitud por los padres y descendencia virtuosa", "Señor mío, inspírame para que agradezca Tu favor que me has concedido a mí y a mis padres, y para que haga buenas obras que Te complazcan, y hazme bien a mi descendencia. En verdad me arrepiento ante Ti y soy de los musulmanes.", "Súplica coránica para quien alcanza los cuarenta años.", "Gratitud, buenas obras y rectitud de la descendencia reunidas en una sola súplica."),
        "dua_intimacy" to DuaText("Antes de la intimidad conyugal", "En el nombre de Allah. Oh Allah, apártanos del demonio y aparta al demonio de lo que nos concedas.", "Antes de la intimidad conyugal.", "Si se concede un hijo, el diablo nunca podrá dañarlo."),
        "dua_ibrahim_children_protection" to DuaText("Protección del hogar y la descendencia", "Señor mío, haz de esta ciudad un lugar seguro, y apártame a mí y a mis hijos de adorar ídolos.", "La súplica de Abraham para proteger la ciudad y la descendencia.", "Súplica para la firmeza en el monoteísmo."),
        "dua_drinking_milk" to DuaText("Al beber leche", "Oh Allah, bendícenosla y auméntanosla.", "Al beber leche.", "La leche equivale tanto a comida como a bebida."),
        "dua_iftar_host" to DuaText("Al romper el ayuno en casa de alguien", "Que los que ayunan rompan el ayuno en vuestra casa, que las personas virtuosas coman vuestra comida, y que los ángeles rueguen por vosotros.", "Al romper el ayuno en casa de alguien.", "La súplica profética para el anfitrión."),
        "dua_seeing_first_fruit" to DuaText("Al ver el primer fruto", "Oh Allah, bendice nuestros frutos, bendice nuestra ciudad, bendice nuestro sa' y nuestro mudd (nuestras medidas).", "Al ver el primer fruto de la temporada.", "Súplica para la bendición del sustento y la ciudad."),
        "dua_good_news" to DuaText("Al recibir una buena noticia", "Alabado sea Allah, por cuyo favor se completan las buenas obras.", "Al recibir una buena noticia (y postración de gratitud).", "El Profeta ﷺ lo decía al ver algo que le agradaba."),
        "dua_looking_mirror" to DuaText("Al mirarse en el espejo", "Oh Allah, así como has embellecido mi apariencia, embellece también mi carácter.", "Al mirarse en el espejo.", "El Profeta ﷺ hacía esta súplica."),
        "dua_rabbana_taqabbal" to DuaText("La aceptación de las obras", "Señor nuestro, acepta esto de nosotros; en verdad Tú eres el que todo lo oye, el que todo lo sabe. Y acepta nuestro arrepentimiento; en verdad Tú eres el Indulgente, el Misericordioso.", "La súplica de Abraham e Ismael al construir la Kaaba.", "Súplica para la aceptación de una buena obra después de completarla."),
    )
}
